import unittest

from solution import emit_expression


class EmitExpressionTests(unittest.TestCase):
    def test_literals_variables_and_nested_binary_expressions(self):
        self.assertEqual(emit_expression(0), "0")
        self.assertEqual(emit_expression(-42), "-42")
        self.assertEqual(emit_expression(("var", "_item9")), "_item9")
        tree = ("/", ("*", ("+", 1, ("var", "x")), 3), ("-", 9, 4))
        self.assertEqual(emit_expression(tree), "(((1+x)*3)/(9-4))")

    def test_every_binary_expression_including_root_is_parenthesized(self):
        self.assertEqual(emit_expression(("+", 1, 2)), "(1+2)")
        self.assertEqual(emit_expression(("-", 5, ("/", 8, 2))), "(5-(8/2))")

    def test_valid_ascii_identifier_boundaries(self):
        for name in ("a", "Z", "_", "a0", "A_b9"):
            with self.subTest(name=name):
                self.assertEqual(emit_expression(("var", name)), name)

    def test_booleans_and_other_unsupported_literals_are_rejected(self):
        for node in (True, False, None, 1.0, "x", ["var", "x"]):
            with self.subTest(node=node):
                with self.assertRaises(ValueError):
                    emit_expression(node)

    def test_malformed_variables_are_rejected(self):
        for name in ("", "9name", "two words", "a-b", "é", "aé", 4, None):
            with self.subTest(name=name):
                with self.assertRaises(ValueError):
                    emit_expression(("var", name))
        for node in (("var",), ("var", "x", "extra")):
            with self.assertRaises(ValueError):
                emit_expression(node)

    def test_malformed_operators_and_children_are_rejected(self):
        invalid = [
            ("%", 1, 2),
            ("+", 1),
            ("+", 1, 2, 3),
            (1, 2, 3),
            ("+", True, 2),
            ("*", 1, []),
            (),
        ]
        for node in invalid:
            with self.subTest(node=node):
                with self.assertRaises(ValueError):
                    emit_expression(node)

    def test_input_tree_is_not_mutated(self):
        tree = ("+", ("var", "left"), ("*", 2, 3))
        before = ("+", ("var", "left"), ("*", 2, 3))
        emit_expression(tree)
        self.assertEqual(tree, before)


if __name__ == "__main__":
    unittest.main()

